/**
 * Returns a debounced version of `fn` that waits until `delay` ms have
 * passed since the last call before invoking `fn`. The final call's
 * arguments and `this` context are used.
 *
 * The returned function also has:
 *   .cancel() – drop any pending invocation
 *   .flush()  – run the pending invocation immediately (if any)
 */
function debounce(fn, delay) {
  if (typeof fn !== 'function') {
    throw new TypeError('debounce: fn must be a function');
  }

  let timerId = null;
  let lastArgs;
  let lastThis;

  function invoke() {
    const args = lastArgs;
    const ctx = lastThis;
    timerId = null;
    lastArgs = lastThis = undefined;
    return fn.apply(ctx, args);
  }

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;
    clearTimeout(timerId);
    timerId = setTimeout(invoke, delay);
  }

  debounced.cancel = function () {
    clearTimeout(timerId);
    timerId = null;
    lastArgs = lastThis = undefined;
  };

  debounced.flush = function () {
    if (timerId !== null) {
      clearTimeout(timerId);
      return invoke();
    }
  };

  return debounced;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = debounce;
}

