import csv
from decimal import Decimal


def sum_amounts(path="sales.csv"):
    total = Decimal("0")
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            value = (row.get("amount") or "").strip()
            if value:
                total += Decimal(value)
    return total


if __name__ == "__main__":
    print(sum_amounts())

