import { useEffect, useRef, useState } from "react";

function formatTime(totalSeconds) {
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = totalSeconds % 60;
  const pad = (n) => String(n).padStart(2, "0");
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
}

/**
 * Countdown timer.
 *
 * Props:
 *  - seconds:    number of seconds to count down from (required)
 *  - autoStart:  start immediately on mount (default true)
 *  - onComplete: called once when the timer reaches 0
 */
export default function CountdownTimer({ seconds, autoStart = true, onComplete }) {
  const [remaining, setRemaining] = useState(seconds);
  const [running, setRunning] = useState(autoStart && seconds > 0);

  // Track the absolute end time so the timer doesn't drift when
  // intervals are delayed (e.g. background tabs).
  const endTimeRef = useRef(null);
  const onCompleteRef = useRef(onComplete);
  onCompleteRef.current = onComplete;

  // Reset when the `seconds` prop changes.
  useEffect(() => {
    setRemaining(seconds);
    setRunning(autoStart && seconds > 0);
  }, [seconds, autoStart]);

  useEffect(() => {
    if (!running) return;

    endTimeRef.current = Date.now() + remaining * 1000;

    const id = setInterval(() => {
      const left = Math.max(0, Math.ceil((endTimeRef.current - Date.now()) / 1000));
      setRemaining(left);
      if (left === 0) {
        clearInterval(id);
        setRunning(false);
        onCompleteRef.current?.();
      }
    }, 250);

    return () => clearInterval(id);
    // `remaining` is intentionally read only when (re)starting.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [running]);

  const toggle = () => {
    if (remaining > 0) setRunning((r) => !r);
  };

  const reset = () => {
    setRunning(false);
    setRemaining(seconds);
  };

  return (
    <div className="countdown-timer">
      <div
        className="countdown-display"
        role="timer"
        aria-live="off"
        style={{ fontSize: "3rem", fontVariantNumeric: "tabular-nums" }}
      >
        {formatTime(remaining)}
      </div>
      <div className="countdown-controls" style={{ display: "flex", gap: "0.5rem" }}>
        <button onClick={toggle} disabled={remaining === 0}>
          {running ? "Pause" : "Start"}
        </button>
        <button onClick={reset}>Reset</button>
      </div>
      {remaining === 0 && <p role="status">Time's up!</p>}
    </div>
  );
}

