import { useEffect, useState } from "react";

export default function Countdown({ seconds }) {
  const [left, setLeft] = useState(seconds);

  // Restart when the parent passes a new starting value.
  useEffect(() => setLeft(seconds), [seconds]);

  useEffect(() => {
    if (left <= 0) return;
    // shortcut: chained 1s timeouts drift a few ms per tick, switch to Date.now() deltas if long timers must stay exact
    const id = setTimeout(() => setLeft(left - 1), 1000);
    return () => clearTimeout(id);
  }, [left]);

  return <span role="timer">{left}</span>;
}

